<?php
if(!defined('ABSPATH')){exit;}function ip_core_add_learning_endpoint():void{add_rewrite_endpoint('learning-library',EP_ROOT|EP_PAGES);}add_action('init','ip_core_add_learning_endpoint');
function ip_core_account_menu(array $items):array{$new=array();foreach($items as $key=>$label){$new[$key]=$label;if('orders'===$key){$new['learning-library']=__('Learning Library','illuminated-path-core');}}if(!isset($new['learning-library'])){$new['learning-library']=__('Learning Library','illuminated-path-core');}return $new;}add_filter('woocommerce_account_menu_items','ip_core_account_menu');
function ip_core_customer_product_ids(int $user_id):array{$orders=wc_get_orders(array('customer_id'=>$user_id,'status'=>wc_get_is_paid_statuses(),'limit'=>-1,'return'=>'objects'));$ids=array();foreach($orders as $order){foreach($order->get_items() as $item){$ids[]=$item->get_variation_id()?:$item->get_product_id();if($item->get_variation_id()){$ids[]=$item->get_product_id();}}}return array_values(array_unique(array_filter(array_map('absint',$ids))));}
function ip_core_account_learning_library():void{if(!is_user_logged_in()){return;}$resources=array();foreach(ip_core_customer_product_ids(get_current_user_id()) as $product_id){$product=wc_get_product($product_id);if($product&&($product->get_meta('_ip_interactive_url')||$product->get_meta('_ip_audio_url')||$product->get_meta('_ip_course_url'))){$resources[]=$product;}}echo '<div class="ip-learning-library"><h2>'.esc_html__('Your Learning Library','illuminated-path-core').'</h2>';if(empty($resources)){echo '<p>'.esc_html__('Interactive resources linked to your purchased books will appear here.','illuminated-path-core').'</p></div>';return;}echo '<div class="ip-learning-grid">';foreach($resources as $product){$url=wp_nonce_url(add_query_arg(array('ip_resource'=>$product->get_id()),home_url('/')),'ip_resource_'.$product->get_id());echo '<article class="ip-learning-card">'.wp_kses_post($product->get_image('woocommerce_thumbnail')).'<div><h3>'.esc_html($product->get_name()).'</h3><a class="button" href="'.esc_url($url).'">'.esc_html__('Open learning resources','illuminated-path-core').'</a></div></article>';}echo '</div></div>';}add_action('woocommerce_account_learning-library_endpoint','ip_core_account_learning_library');
function ip_core_customer_can_access_product(int $user_id,WC_Product $product):bool{$user=get_userdata($user_id);$email=$user?(string)$user->user_email:'';$allowed=$email?wc_customer_bought_product($email,$user_id,$product->get_id()):false;return(bool)apply_filters('illuminated_path_customer_can_access_product_resource',$allowed,$user_id,$product);}
function ip_core_resource_redirect():void{if(empty($_GET['ip_resource'])){return;}$product_id=absint($_GET['ip_resource']);$product=wc_get_product($product_id);if(!$product){wp_die(esc_html__('Resource not found.','illuminated-path-core'),'',array('response'=>404));}if(!is_user_logged_in()){wp_safe_redirect(wc_get_page_permalink('myaccount'));exit;}if(!isset($_GET['_wpnonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_GET['_wpnonce'])),'ip_resource_'.$product_id)){wp_die(esc_html__('The resource link is invalid or expired.','illuminated-path-core'),'',array('response'=>403));}if(!ip_core_customer_can_access_product(get_current_user_id(),$product)){wp_die(esc_html__('This resource is available to customers who purchased this book.','illuminated-path-core'),'',array('response'=>403));}$target=$product->get_meta('_ip_interactive_url')?:($product->get_meta('_ip_course_url')?:$product->get_meta('_ip_audio_url'));if(!$target){wp_die(esc_html__('No learning resource has been attached to this product yet.','illuminated-path-core'),'',array('response'=>404));}wp_redirect(esc_url_raw($target));exit;}add_action('template_redirect','ip_core_resource_redirect');
